###############################################################################
## ars.R -- Adaptive Rejection Sampling (Gilks, W. R. & Wild, P., 1992)
##
## Public interface
##   ars(density_function, domain, n = sample_count, ...)  -- draw n samples
##   test(...)                                             -- formal test suite
##
## Design notes
##   * Functional (not OOP) style throughout; the piecewise-exponential
##     envelope ("hull") is a plain list produced by build_hull() and consumed
##     by eval_upper_hull() / eval_lower_hull() / sample_upper_hull().
##   * All auxiliary functions are prefixed by their task, use snake_case
##     names, take the log-density `logf` and its derivative `dlogf` as
##     arguments, and never touch global state.
##   * Everything is done on the log scale for numerical stability; the user
##     supplies a possibly unnormalised density (vectorised, e.g. dnorm).
###############################################################################

ARS_TOL <- 1e-5          # relative tolerance used by all log-concavity checks


## ---------------------------------------------------------------------------
## 1. Input validation
## ---------------------------------------------------------------------------
validate_inputs <- function(density_function, domain, n,
                            log_density = FALSE, deriv = NULL,
                            max_abscissae = 100) {
  if (missing(density_function) || is.null(density_function))
    stop("ars: 'density_function' must be supplied")
  if (!is.function(density_function))
    stop("ars: 'density_function' must be a function of one argument ",
         "returning the (possibly unnormalised) density in a vectorised way")

  if (!is.numeric(domain) || length(domain) != 2L || any(is.na(domain)))
    stop("ars: 'domain' must be a numeric vector of length 2, c(lower, upper)")
  if (!(domain[1] < domain[2]))
    stop("ars: invalid domain -- lower bound must be strictly less than ",
         "upper bound")

  if (!is.numeric(n) || length(n) != 1L || is.na(n) || !is.finite(n))
    stop("ars: 'n' must be a single finite number")
  if (n < 1)
    stop("ars: 'n' must be a positive integer (got ", n, ")")
  if (abs(n - round(n)) > 0)
    stop("ars: 'n' must be a whole number (got ", n, ")")

  if (!is.logical(log_density) || length(log_density) != 1L || is.na(log_density))
    stop("ars: 'log_density' must be TRUE or FALSE")
  if (!is.null(deriv) && !is.function(deriv))
    stop("ars: 'deriv', if supplied, must be a function")
  if (!is.numeric(max_abscissae) || length(max_abscissae) != 1L ||
      max_abscissae < 2)
    stop("ars: 'max_abscissae' must be a single number >= 2")

  invisible(TRUE)
}


## ---------------------------------------------------------------------------
## 2. Log density and its derivative
## ---------------------------------------------------------------------------
make_log_density <- function(density_function, log_density = FALSE,
                             domain = c(-Inf, Inf), ...) {
  extra <- list(...)
  lb <- domain[1]; ub <- domain[2]
  function(x) {
    val <- rep(-Inf, length(x))
    inside <- !is.na(x) & x >= lb & x <= ub
    if (any(inside)) {
      fx <- do.call(density_function, c(list(x[inside]), extra))
      if (length(fx) != sum(inside))
        stop("ars: 'density_function' is not vectorised -- it must return one ",
             "value per input value")
      if (!is.numeric(fx))
        stop("ars: 'density_function' must return numeric values")
      if (log_density) {
        val[inside] <- fx
      } else {
        if (any(fx < 0, na.rm = TRUE))
          stop("ars: 'density_function' returned negative values -- it is not ",
               "a density")
        val[inside] <- suppressWarnings(log(fx))
      }
    }
    val[is.na(val)] <- -Inf
    val
  }
}

numeric_derivative <- function(logf, x, lb = -Inf, ub = Inf, eps = 1e-6) {
  vapply(x, function(xi) {
    step <- eps * max(1, abs(xi))
    xl <- xi - step; xr <- xi + step
    hl <- if (xl > lb) logf(xl) else -Inf
    hr <- if (xr < ub) logf(xr) else -Inf
    hc <- logf(xi)
    if (is.finite(hl) && is.finite(hr)) return((hr - hl) / (2 * step))
    if (is.finite(hr) && is.finite(hc)) return((hr - hc) / step)
    if (is.finite(hl) && is.finite(hc)) return((hc - hl) / step)
    NA_real_
  }, numeric(1))
}

make_derivative <- function(logf, deriv = NULL, domain = c(-Inf, Inf), ...) {
  if (is.null(deriv)) {
    function(x) numeric_derivative(logf, x, domain[1], domain[2])
  } else {
    extra <- list(...)
    function(x) {
      d <- do.call(deriv, c(list(x), extra))
      if (length(d) != length(x))
        stop("ars: 'deriv' must be vectorised")
      as.numeric(d)
    }
  }
}


## ---------------------------------------------------------------------------
## 3. Starting abscissae
## ---------------------------------------------------------------------------
## Search outwards from x0 for a point whose log-density derivative has the
## sign needed to make the exponential tail of the hull integrable
## (direction = -1: need h' > 0, direction = +1: need h' < 0).
expand_side <- function(logf, dlogf, x0, direction, max_iter = 200) {
  good <- x0
  step <- 1
  for (i in seq_len(max_iter)) {
    p <- good + direction * step
    if (is.finite(logf(p))) {
      d <- dlogf(p)
      if (is.finite(d) && direction * d < 0) return(p)
      good <- p
      step <- step * 2
    } else {
      step <- step / 2
      if (step < 1e-12) break
    }
  }
  NULL
}

find_interior_point <- function(logf, lb, ub) {
  start <- if (is.finite(lb) && is.finite(ub)) (lb + ub) / 2 else
           if (is.finite(lb)) lb + 1 else
           if (is.finite(ub)) ub - 1 else 0
  if (is.finite(lb) && is.finite(ub)) start <- min(max(start, lb), ub)
  if (is.finite(logf(start))) return(start)
  ## fall back on a widening / shrinking search inside the domain
  span <- if (is.finite(ub - lb)) (ub - lb) else 1
  for (f in c(0.5, 0.25, 0.1, 0.05, 1e-2, 1e-3, 1e-4)) {
    for (cand in c(start + f * span, start - f * span,
                   lb + f * span, ub - f * span)) {
      if (is.finite(cand) && cand > lb && cand < ub && is.finite(logf(cand)))
        return(cand)
    }
  }
  for (cand in c(0, 1, -1, 10, -10, 100, -100)) {
    if (cand > lb && cand < ub && is.finite(logf(cand))) return(cand)
  }
  stop("ars: could not find a point inside the domain where the density is ",
       "positive and finite; please supply a narrower 'domain' or check ",
       "'density_function'")
}

init_abscissae <- function(logf, dlogf, lb, ub) {
  x0 <- find_interior_point(logf, lb, ub)
  span <- if (is.finite(ub - lb)) (ub - lb) else 1
  cand <- x0

  if (is.finite(lb)) {
    for (f in c(0.25, 0.1, 0.01, 1e-3, 1e-4)) {
      p <- lb + f * span
      if (p < x0 && is.finite(logf(p)) && is.finite(dlogf(p))) {
        cand <- c(cand, p); break
      }
    }
  } else {
    p <- expand_side(logf, dlogf, x0, -1)
    if (is.null(p))
      stop("ars: failed to find a starting point with positive log-density ",
           "slope on the left tail; the density may not be log-concave or ",
           "may not be integrable on the given domain")
    cand <- c(cand, p)
  }

  if (is.finite(ub)) {
    for (f in c(0.25, 0.1, 0.01, 1e-3, 1e-4)) {
      p <- ub - f * span
      if (p > x0 && is.finite(logf(p)) && is.finite(dlogf(p))) {
        cand <- c(cand, p); break
      }
    }
  } else {
    p <- expand_side(logf, dlogf, x0, +1)
    if (is.null(p))
      stop("ars: failed to find a starting point with negative log-density ",
           "slope on the right tail; the density may not be log-concave or ",
           "may not be integrable on the given domain")
    cand <- c(cand, p)
  }

  cand <- sort(unique(cand[is.finite(cand)]))
  keep <- is.finite(logf(cand)) & is.finite(dlogf(cand))
  cand <- cand[keep]
  if (length(cand) < 1L)
    stop("ars: could not initialise the sampler -- no usable starting points")
  cand
}


## ---------------------------------------------------------------------------
## 4. Log-concavity checks
## ---------------------------------------------------------------------------
check_log_concavity <- function(x, h, hp, tol = ARS_TOL) {
  k <- length(x)
  if (any(!is.finite(h)) || any(!is.finite(hp)))
    stop("ars: non-finite log-density or derivative at an abscissa -- ",
         "cannot build the envelope")
  if (k >= 2L) {
    slack <- tol * (1 + max(abs(hp)))
    bad <- which(diff(hp) > slack)
    if (length(bad))
      stop("ars: the density does not appear to be log-concave -- the ",
           "derivative of log(f) increases between x = ",
           signif(x[bad[1]], 6), " and x = ", signif(x[bad[1] + 1], 6),
           " (h' = ", signif(hp[bad[1]], 6), " -> ",
           signif(hp[bad[1] + 1], 6), ")")
    ## secant/tangent test: each tangent must dominate the neighbouring point
    sl <- tol * (1 + max(abs(h)))
    up_r <- h[-k] + (x[-1] - x[-k]) * hp[-k]      # tangent at x_j at x_{j+1}
    up_l <- h[-1] + (x[-k] - x[-1]) * hp[-1]      # tangent at x_{j+1} at x_j
    if (any(h[-1] > up_r + sl) || any(h[-k] > up_l + sl))
      stop("ars: the density does not appear to be log-concave -- log(f) ",
           "lies above one of its tangent lines")
  }
  invisible(TRUE)
}


## ---------------------------------------------------------------------------
## 5. The envelope (upper hull) and squeeze (lower hull)
## ---------------------------------------------------------------------------
## Returns a list with abscissae x, values h, slopes hp, tangent intersection
## points z (length k + 1, z[1] = lower bound, z[k+1] = upper bound), segment
## intercepts/slopes a, b, and the (normalised) segment probabilities.
build_hull <- function(x, h, hp, lb, ub, tol = ARS_TOL) {
  ord <- order(x)
  x <- x[ord]; h <- h[ord]; hp <- hp[ord]
  check_log_concavity(x, h, hp, tol)
  k <- length(x)

  z <- numeric(k + 1L)
  z[1] <- lb
  z[k + 1L] <- ub
  if (k >= 2L) {
    dh <- hp[-k] - hp[-1]
    num <- h[-1] - h[-k] - x[-1] * hp[-1] + x[-k] * hp[-k]
    zz <- ifelse(abs(dh) < 1e-12, (x[-k] + x[-1]) / 2, num / dh)
    ## keep intersections inside their bracketing abscissae (numerical safety)
    zz <- pmin(pmax(zz, x[-k]), x[-1])
    z[2:k] <- zz
  }
  if (any(diff(z) < 0))
    stop("ars: failed to build a valid envelope (tangent intersections are ",
         "not ordered); the density may not be log-concave")

  a <- h - x * hp        # u(t) = a[j] + b[j] * t on [z[j], z[j+1]]
  b <- hp

  ## log of the integral of exp(a + b t) over each segment
  zl <- z[-(k + 1L)]; zr <- z[-1]
  log_int <- numeric(k)
  flat <- abs(b) < 1e-12
  if (any(flat)) {
    len <- zr[flat] - zl[flat]
    if (any(!is.finite(len)))
      stop("ars: the envelope has infinite mass (a flat segment on an ",
           "unbounded interval); the density is not integrable on this domain")
    log_int[flat] <- a[flat] + log(len)
  }
  if (any(!flat)) {
    i <- which(!flat)
    m <- pmax(b[i] * zr[i], b[i] * zl[i])
    d <- abs(b[i] * (zr[i] - zl[i]))
    log_int[i] <- a[i] + m + log(-expm1(-d)) - log(abs(b[i]))
  }
  if (any(!is.finite(log_int)))
    stop("ars: the envelope has infinite or undefined mass -- the density ",
         "may not be log-concave or not integrable on the given domain")

  mx <- max(log_int)
  prob <- exp(log_int - mx)
  prob <- prob / sum(prob)

  list(x = x, h = h, hp = hp, z = z, a = a, b = b, k = k,
       log_int = log_int, prob = prob, lb = lb, ub = ub)
}

eval_upper_hull <- function(hull, x) {
  j <- findInterval(x, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  j <- pmin(pmax(j, 1L), hull$k)
  hull$a[j] + hull$b[j] * x
}

eval_lower_hull <- function(hull, x) {
  xs <- hull$x; hs <- hull$h; k <- hull$k
  out <- rep(-Inf, length(x))
  if (k < 2L) return(out)
  inside <- x >= xs[1] & x <= xs[k]
  if (any(inside)) {
    xi <- x[inside]
    j <- pmin(pmax(findInterval(xi, xs, all.inside = TRUE), 1L), k - 1L)
    w <- (xi - xs[j]) / (xs[j + 1L] - xs[j])
    out[inside] <- (1 - w) * hs[j] + w * hs[j + 1L]
  }
  out
}

## Inverse-CDF sampling from the piecewise exponential envelope.
sample_upper_hull <- function(hull, m) {
  k <- hull$k
  j <- if (k == 1L) rep(1L, m) else
       sample.int(k, size = m, replace = TRUE, prob = hull$prob)
  zl <- hull$z[j]; zr <- hull$z[j + 1L]; b <- hull$b[j]
  len <- zr - zl
  w <- runif(m)
  w <- pmin(pmax(w, 1e-300), 1 - 1e-16)
  x <- numeric(m)
  flat <- abs(b) < 1e-12
  pos  <- !flat & b > 0
  neg  <- !flat & b < 0
  if (any(flat)) x[flat] <- zl[flat] + w[flat] * len[flat]
  if (any(pos))
    x[pos] <- zr[pos] +
      log(w[pos] + (1 - w[pos]) * exp(-b[pos] * len[pos])) / b[pos]
  if (any(neg))
    x[neg] <- zl[neg] +
      log(1 - w[neg] + w[neg] * exp(b[neg] * len[neg])) / b[neg]
  ## numerical safety: keep draws strictly inside the domain
  lo <- if (is.finite(hull$lb)) hull$lb else -Inf
  hi <- if (is.finite(hull$ub)) hull$ub else  Inf
  x <- pmin(pmax(x, lo), hi)
  x[is.finite(x)]
}

## Add newly evaluated points to the hull (used for the adaptive update).
update_hull <- function(hull, new_x, new_h, dlogf, max_abscissae = 100,
                        tol = ARS_TOL) {
  keep <- is.finite(new_x) & is.finite(new_h)
  new_x <- new_x[keep]; new_h <- new_h[keep]
  if (!length(new_x)) return(hull)
  o <- order(new_x)
  new_x <- new_x[o]; new_h <- new_h[o]
  dup <- duplicated(c(hull$x, new_x))[-seq_along(hull$x)]
  new_x <- new_x[!dup]; new_h <- new_h[!dup]
  room <- max_abscissae - hull$k
  if (room <= 0 || !length(new_x)) return(hull)
  if (length(new_x) > room) {
    sel <- unique(round(seq(1, length(new_x), length.out = room)))
    new_x <- new_x[sel]; new_h <- new_h[sel]
  }
  new_hp <- dlogf(new_x)
  ok <- is.finite(new_hp)
  if (!any(ok)) return(hull)
  build_hull(c(hull$x, new_x[ok]), c(hull$h, new_h[ok]),
             c(hull$hp, new_hp[ok]), hull$lb, hull$ub, tol)
}


## ---------------------------------------------------------------------------
## 6. The sampler
## ---------------------------------------------------------------------------
ars <- function(density_function, domain = c(-Inf, Inf), n = 100,
                log_density = FALSE, deriv = NULL, max_abscissae = 100L,
                verbose = FALSE, ...) {
  validate_inputs(density_function, domain, n, log_density, deriv,
                  max_abscissae)
  n <- as.integer(round(n))
  lb <- domain[1]; ub <- domain[2]

  logf  <- make_log_density(density_function, log_density, domain, ...)
  dlogf <- make_derivative(logf, deriv, domain, ...)

  x_init <- init_abscissae(logf, dlogf, lb, ub)
  hull <- build_hull(x_init, logf(x_init), dlogf(x_init), lb, ub)

  samples <- numeric(n)
  n_acc <- 0L
  n_draw <- 0L
  max_draw <- 1000L * n + 10000L

  while (n_acc < n) {
    need <- n - n_acc
    m <- as.integer(min(max(10L, ceiling(need * 1.2)), 5000L))
    cand <- sample_upper_hull(hull, m)
    if (!length(cand)) stop("ars: envelope sampling produced no valid draws")
    n_draw <- n_draw + length(cand)
    if (n_draw > max_draw)
      stop("ars: too many rejections (", n_draw, " draws for ", n_acc,
           " accepted samples) -- check 'density_function' and 'domain'")

    u_val <- eval_upper_hull(hull, cand)
    l_val <- eval_lower_hull(hull, cand)
    lw <- log(runif(length(cand)))

    acc <- lw <= (l_val - u_val)            # squeezing test
    idx <- which(!acc)
    if (length(idx)) {
      hx <- logf(cand[idx])
      ## --- log-concavity checks during sampling -------------------------
      fin <- is.finite(hx)
      if (any(fin)) {
        slack <- ARS_TOL * (1 + abs(hx[fin]))
        if (any(hx[fin] > u_val[idx][fin] + slack)) {
          w <- which(hx[fin] > u_val[idx][fin] + slack)[1]
          stop("ars: the density does not appear to be log-concave -- ",
               "log(f) exceeds the upper hull at x = ",
               signif(cand[idx][fin][w], 6), " (log f = ",
               signif(hx[fin][w], 6), ", hull = ",
               signif(u_val[idx][fin][w], 6), ")")
        }
        lv <- l_val[idx][fin]
        bad_lo <- is.finite(lv) & (lv > hx[fin] + slack)
        if (any(bad_lo))
          stop("ars: the density does not appear to be log-concave -- ",
               "log(f) falls below the squeezing (lower) hull at x = ",
               signif(cand[idx][fin][which(bad_lo)[1]], 6))
      }
      acc[idx] <- lw[idx] <= (hx - u_val[idx])
      hull <- update_hull(hull, cand[idx], hx, dlogf, max_abscissae)
    }

    got <- cand[acc]
    if (length(got)) {
      take <- min(length(got), need)
      samples[(n_acc + 1L):(n_acc + take)] <- got[seq_len(take)]
      n_acc <- n_acc + take
    }
  }

  if (verbose)
    message(sprintf("ars: %d samples from %d envelope draws (acceptance %.3f), %d abscissae",
                    n, n_draw, n / n_draw, hull$k))
  attr(samples, "n_draws") <- n_draw
  attr(samples, "abscissae") <- hull$x
  samples
}


###############################################################################
## 7. Formal tests
###############################################################################
.report <- function(name, passed, extra = "") {
  cat(sprintf("%s: %s%s\n", name, if (passed) "PASS" else "FAIL",
              if (nzchar(extra)) paste0("  [", extra, "]") else ""))
  invisible(isTRUE(passed))
}

.stats_string <- function(x, mean_true = NA, sd_true = NA) {
  s <- sprintf("mean = %.4f, sd = %.4f", mean(x), sd(x))
  if (!is.na(mean_true))
    s <- paste0(s, sprintf("; true mean = %.4f, true sd = %.4f",
                           mean_true, sd_true))
  s
}

## Distribution test: compares samples with a known truth using the
## Kolmogorov-Smirnov statistic plus mean / sd agreement.
test_distribution <- function(name, density_function, domain, cdf,
                              mean_true, sd_true, n = 4000,
                              ks_alpha = 0.001, tol_moments = 0.08, ...) {
  cat(sprintf("\n-- Testing ars() against %s: drawing %d samples on [%s, %s]\n",
              name, n, format(domain[1]), format(domain[2])))
  x <- try(ars(density_function, domain, n = n, ...), silent = TRUE)
  if (inherits(x, "try-error")) {
    .report(paste0(name, "_SAMPLING"), FALSE, as.character(x))
    return(list(passed = FALSE, samples = NULL))
  }
  x <- as.numeric(x)
  ks <- suppressWarnings(stats::ks.test(x, cdf))
  in_domain <- all(x >= domain[1] & x <= domain[2]) && length(x) == n &&
               all(is.finite(x))
  m_ok <- abs(mean(x) - mean_true) < tol_moments * (sd_true + abs(mean_true))
  s_ok <- abs(sd(x) - sd_true) < tol_moments * sd_true * 2
  ks_ok <- ks$p.value > ks_alpha
  cat(sprintf("   %s\n   KS D = %.4f, p = %.4f; length = %d, all in domain = %s\n",
              .stats_string(x, mean_true, sd_true), ks$statistic,
              ks$p.value, length(x), in_domain))
  passed <- in_domain && m_ok && s_ok && ks_ok
  .report(paste0(name, "_DISTRIBUTION"), passed,
          .stats_string(x, mean_true, sd_true))
  if (!passed) {
    if (!in_domain) cat("   -> failure: samples outside domain / wrong count\n")
    if (!m_ok)  cat("   -> failure: sample mean too far from truth\n")
    if (!s_ok)  cat("   -> failure: sample sd too far from truth\n")
    if (!ks_ok) cat("   -> failure: KS test rejects the target distribution\n")
  }
  list(passed = passed, samples = x)
}

test_validation <- function() {
  cat("\n-- Testing input validation: each call below must raise an error\n")
  cases <- list(
    NEGATIVE_N        = function() ars(dnorm, c(-Inf, Inf), n = -5),
    ZERO_N            = function() ars(dnorm, c(-Inf, Inf), n = 0),
    NON_INTEGER_N     = function() ars(dnorm, c(-Inf, Inf), n = 10.5),
    NA_N              = function() ars(dnorm, c(-Inf, Inf), n = NA),
    CHARACTER_N       = function() ars(dnorm, c(-Inf, Inf), n = "many"),
    REVERSED_DOMAIN   = function() ars(dnorm, c(5, -5), n = 10),
    DEGENERATE_DOMAIN = function() ars(dnorm, c(1, 1), n = 10),
    DOMAIN_LENGTH     = function() ars(dnorm, c(0, 1, 2), n = 10),
    DOMAIN_NA         = function() ars(dnorm, c(NA, 1), n = 10),
    DOMAIN_TYPE       = function() ars(dnorm, "whole line", n = 10),
    NOT_A_FUNCTION    = function() ars("dnorm", c(-Inf, Inf), n = 10),
    NEGATIVE_DENSITY  = function() ars(function(x) -exp(-x^2), c(-Inf, Inf), 10)
  )
  ok <- TRUE
  for (nm in names(cases)) {
    err <- inherits(try(cases[[nm]](), silent = TRUE), "try-error")
    ok <- .report(paste0("VALIDATION_", nm), err,
                  if (err) "error correctly raised" else
                    "no error raised") && ok
  }
  ok
}

test_log_concavity_checks <- function() {
  cat("\n-- Testing log-concavity detection: non-log-concave densities must fail\n")
  cases <- list(
    CAUCHY   = list(f = function(x) dcauchy(x), dom = c(-Inf, Inf)),
    T_DF2    = list(f = function(x) dt(x, df = 2), dom = c(-Inf, Inf)),
    PARETO   = list(f = function(x) 1 / x^2, dom = c(1, Inf)),
    BIMODAL  = list(f = function(x) dnorm(x, -4) + dnorm(x, 4),
                    dom = c(-10, 10)),
    CONVEXLOG = list(f = function(x) exp(x^2), dom = c(-2, 2))
  )
  ok <- TRUE
  for (nm in names(cases)) {
    res <- try(ars(cases[[nm]]$f, cases[[nm]]$dom, n = 500), silent = TRUE)
    err <- inherits(res, "try-error")
    msg <- if (err) trimws(sub(".*Error[^:]*:", "", as.character(res)))
           else "no error raised"
    ok <- .report(paste0("LOG_CONCAVITY_", nm), err,
                  substr(gsub("\n", " ", msg), 1, 90)) && ok
  }
  ## a genuinely log-concave density must NOT trigger the checks
  res <- try(ars(dnorm, c(-Inf, Inf), n = 500), silent = TRUE)
  ok <- .report("LOG_CONCAVITY_NORMAL_NOT_FLAGGED",
                !inherits(res, "try-error"),
                "log-concave density accepted") && ok
  ok
}

test_derivative <- function() {
  cat("\n-- Testing numeric_derivative() against analytic derivatives\n")
  logf <- make_log_density(dnorm, domain = c(-Inf, Inf))
  xs <- c(-3, -1, -0.2, 0, 0.5, 2, 4)
  num <- numeric_derivative(logf, xs)
  err1 <- max(abs(num - (-xs)))
  ok1 <- .report("MODULE_NUMERIC_DERIVATIVE_NORMAL", err1 < 1e-4,
                 sprintf("max abs error = %.3e", err1))

  logf2 <- make_log_density(function(x) dgamma(x, shape = 3, rate = 2),
                            domain = c(0, Inf))
  xs2 <- c(0.3, 1, 2, 5)
  num2 <- numeric_derivative(logf2, xs2, lb = 0)
  ana2 <- 2 / xs2 - 2
  err2 <- max(abs(num2 - ana2))
  ok2 <- .report("MODULE_NUMERIC_DERIVATIVE_GAMMA", err2 < 1e-4,
                 sprintf("max abs error = %.3e", err2))
  ok1 && ok2
}

test_hull <- function() {
  cat("\n-- Testing build_hull()/eval_upper_hull()/eval_lower_hull(): squeeze <= log f <= hull\n")
  logf  <- make_log_density(dnorm, domain = c(-Inf, Inf))
  dlogf <- make_derivative(logf, domain = c(-Inf, Inf))
  xk <- c(-2, -0.5, 1, 2.5)
  hull <- build_hull(xk, logf(xk), dlogf(xk), -Inf, Inf)
  grid <- seq(-6, 6, length.out = 601)
  hv <- logf(grid); uv <- eval_upper_hull(hull, grid); lv <- eval_lower_hull(hull, grid)
  ok1 <- .report("MODULE_HULL_UPPER_DOMINATES", all(uv >= hv - 1e-8),
                 sprintf("max(log f - upper) = %.3e", max(hv - uv)))
  ok2 <- .report("MODULE_HULL_LOWER_DOMINATED", all(lv <= hv + 1e-8),
                 sprintf("max(lower - log f) = %.3e", max(lv - hv)))
  ok3 <- .report("MODULE_HULL_TANGENCY",
                 max(abs(eval_upper_hull(hull, xk) - logf(xk))) < 1e-8,
                 "hull touches log f at every abscissa")

  ## sample_upper_hull() must reproduce the envelope density itself.
  ## With a single abscissa on [0, Inf) the envelope is exactly Exp(rate = 1).
  logf_e  <- make_log_density(function(x) exp(-x), domain = c(0, Inf))
  dlogf_e <- make_derivative(logf_e, domain = c(0, Inf))
  hull_e  <- build_hull(1, logf_e(1), dlogf_e(1), 0, Inf)
  set.seed(11)
  se <- sample_upper_hull(hull_e, 5000)
  ks <- suppressWarnings(stats::ks.test(se, "pexp"))
  ok4 <- .report("MODULE_SAMPLE_UPPER_HULL", ks$p.value > 0.001,
                 sprintf("%s; KS p = %.4f", .stats_string(se, 1, 1), ks$p.value))

  ## envelope mass of a two-piece hull, checked against numerical integration
  hull2 <- build_hull(c(-1, 1), logf(c(-1, 1)), dlogf(c(-1, 1)), -Inf, Inf)
  num_mass <- integrate(function(t) exp(eval_upper_hull(hull2, t)),
                        -Inf, Inf)$value
  ana_mass <- sum(exp(hull2$log_int))
  ok5 <- .report("MODULE_HULL_MASS",
                 abs(num_mass - ana_mass) / num_mass < 1e-5,
                 sprintf("analytic = %.6f, numeric = %.6f", ana_mass, num_mass))
  ok1 && ok2 && ok3 && ok4 && ok5
}

test_misc <- function() {
  cat("\n-- Testing miscellaneous behaviour (unnormalised input, log input, n = 1)\n")
  set.seed(4)
  x1 <- as.numeric(ars(function(x) 17 * exp(-(x - 3)^2 / 2), c(-Inf, Inf), 3000))
  ok1 <- .report("UNNORMALISED_DENSITY",
                 abs(mean(x1) - 3) < 0.1 && abs(sd(x1) - 1) < 0.1,
                 .stats_string(x1, 3, 1))
  x2 <- as.numeric(ars(function(x) -x^2 / 2, c(-Inf, Inf), 3000,
                       log_density = TRUE))
  ok2 <- .report("LOG_SCALE_INPUT",
                 abs(mean(x2)) < 0.1 && abs(sd(x2) - 1) < 0.1,
                 .stats_string(x2, 0, 1))
  x3 <- as.numeric(ars(dnorm, c(-Inf, Inf), n = 1))
  ok3 <- .report("SINGLE_SAMPLE", length(x3) == 1 && is.finite(x3),
                 sprintf("value = %.4f", x3))
  x4 <- as.numeric(ars(dnorm, c(-Inf, Inf), 2000, deriv = function(x) -x))
  ok4 <- .report("USER_SUPPLIED_DERIVATIVE",
                 abs(mean(x4)) < 0.12 && abs(sd(x4) - 1) < 0.12,
                 .stats_string(x4, 0, 1))
  set.seed(99); a <- as.numeric(ars(dnorm, c(-Inf, Inf), 50))
  set.seed(99); b <- as.numeric(ars(dnorm, c(-Inf, Inf), 50))
  ok5 <- .report("REPRODUCIBLE_WITH_SEED", identical(a, b),
                 "same seed gives same samples")
  ok1 && ok2 && ok3 && ok4 && ok5
}

## Main test driver -------------------------------------------------------
test <- function(out_dir = "/app", n = 4000, seed = 20250101) {
  cat("===========================================================\n")
  cat(" Adaptive Rejection Sampling (Gilks & Wild 1992) test suite\n")
  cat("===========================================================\n")
  set.seed(seed)
  results <- logical(0)

  results["validation"]    <- test_validation()
  results["derivative"]    <- test_derivative()
  results["hull"]          <- test_hull()
  results["log_concavity"] <- test_log_concavity_checks()

  nrm <- test_distribution("NORMAL", dnorm, c(-Inf, Inf),
                           function(q) pnorm(q), 0, 1, n = n)
  results["normal"] <- nrm$passed

  nrm2 <- test_distribution("NORMAL_MEAN2_SD3",
                            function(x) dnorm(x, 2, 3), c(-Inf, Inf),
                            function(q) pnorm(q, 2, 3), 2, 3, n = n)
  results["normal_scaled"] <- nrm2$passed

  exps <- test_distribution("EXPONENTIAL", function(x) dexp(x, rate = 2),
                            c(0, Inf), function(q) pexp(q, rate = 2),
                            0.5, 0.5, n = n)
  results["exponential"] <- exps$passed

  results["gamma"] <- test_distribution(
    "GAMMA_SHAPE4", function(x) dgamma(x, shape = 4, rate = 1), c(0, Inf),
    function(q) pgamma(q, shape = 4, rate = 1), 4, 2, n = n)$passed

  results["beta"] <- test_distribution(
    "BETA_2_3", function(x) dbeta(x, 2, 3), c(0, 1),
    function(q) pbeta(q, 2, 3), 0.4, sqrt(2 * 3 / (5^2 * 6)), n = n)$passed

  results["uniform"] <- test_distribution(
    "UNIFORM_0_1", function(x) rep(1, length(x)), c(0, 1),
    function(q) punif(q), 0.5, sqrt(1 / 12), n = n)$passed

  results["logistic"] <- test_distribution(
    "LOGISTIC", function(x) dlogis(x), c(-Inf, Inf),
    function(q) plogis(q), 0, pi / sqrt(3), n = n)$passed

  results["chisq"] <- test_distribution(
    "CHISQ_DF4", function(x) dchisq(x, df = 4), c(0, Inf),
    function(q) pchisq(q, df = 4), 4, sqrt(8), n = n)$passed

  ## truncated normal on [-1, 2]
  za <- pnorm(-1); zb <- pnorm(2); zz <- zb - za
  m_tn <- (dnorm(-1) - dnorm(2)) / zz
  v_tn <- 1 + ((-1) * dnorm(-1) - 2 * dnorm(2)) / zz - m_tn^2
  results["truncated_normal"] <- test_distribution(
    "TRUNCATED_NORMAL", dnorm, c(-1, 2),
    function(q) (pnorm(q) - za) / zz, m_tn, sqrt(v_tn), n = n)$passed

  results["misc"] <- test_misc()

  ## ---- write sample files --------------------------------------------
  cat("\n-- Writing sample files\n")
  files_ok <- TRUE
  for (item in list(list(f = "normal_samples.txt", x = nrm$samples),
                    list(f = "exponential_samples.txt", x = exps$samples))) {
    path <- file.path(out_dir, item$f)
    written <- FALSE
    if (!is.null(item$x)) {
      written <- !inherits(try(writeLines(format(item$x, digits = 10), path),
                               silent = TRUE), "try-error") &&
                 file.exists(path)
    }
    if (written) cat(sprintf("   wrote %d samples to %s\n", length(item$x), path))
    files_ok <- .report(paste0("SAMPLE_FILE_", toupper(sub("\\.txt$", "", item$f))),
                        written, path) && files_ok
  }
  results["sample_files"] <- files_ok

  cat("\n===========================================================\n")
  cat(sprintf(" SUMMARY: %d of %d test groups passed\n",
              sum(results), length(results)))
  for (nm in names(results))
    cat(sprintf("   %-20s %s\n", nm, if (results[[nm]]) "PASS" else "FAIL"))
  cat(sprintf(" OVERALL: %s\n", if (all(results)) "PASS" else "FAIL"))
  cat("===========================================================\n")
  invisible(all(results))
}


## Run the test suite when this file is executed directly (Rscript ars.R),
## but not when it is sourced from another script.
if (!interactive()) {
  .argv <- commandArgs(FALSE)
  .file <- sub("^--file=", "", .argv[grepl("^--file=", .argv)])
  if (length(.file) == 1L && identical(basename(.file), "ars.R")) test()
}
